import type { FastifyPluginAsyncZod } from "fastify-type-provider-zod";
import { z } from "zod";
import { CreateExerciseListBody, ErrorResponse, ExerciseList } from "@mento/contracts";
import { notFound } from "../lib/errors";

const Params = z.object({ id: z.string() });

// Owner: Person 1. Exercise lists (D72): generated by Claude for a topic the class struggles with, kept in `exercise_lists`.
// POST answers 202 "generating"; the teacher stream reports `exercise_list_status` when the list is ready or failed.
const plugin: FastifyPluginAsyncZod = async (app) => {
  app.get("/exercise-lists", { schema: { response: { 200: z.array(ExerciseList) } } }, async () => app.container.exerciseLists.list());

  app.get("/exercise-lists/:id", { schema: { params: Params, response: { 200: ExerciseList } } }, async (request) => {
    return (await app.container.exerciseLists.get(request.params.id)) ?? Promise.reject(notFound("exercise list"));
  });

  app.post(
    "/exercise-lists",
    { schema: { body: CreateExerciseListBody, response: { 202: ExerciseList, 400: ErrorResponse, 503: ErrorResponse } } },
    async (request, reply) => {
      const c = app.container;
      if (!c.dbReady()) return reply.status(503).send({ error: "database_unavailable" });
      try {
        return reply.code(202).send(await c.exercises.create(request.body));
      } catch (err) {
        // By code, not instanceof: the service may come from another copy of @mento/analysis (tests, bundling).
        const code = (err as { code?: string }).code;
        if (code === "generator_unavailable" || code === "invalid_gaps") {
          return reply.status(code === "generator_unavailable" ? 503 : 400).send({ error: code, message: (err as Error).message });
        }
        throw err;
      }
    },
  );

  app.delete("/exercise-lists/:id", { schema: { params: Params } }, async (request, reply) => {
    if (!(await app.container.exerciseLists.delete(request.params.id))) throw notFound("exercise list");
    return reply.code(204).send();
  });
};

export default plugin;
